/bin/bash -lc "node --input-type=module <<'EOF'
import {mkdir, writeFile} from 'node:fs/promises';
await mkdir('public/fonts', {recursive:true});
const response = await fetch('https://fonts.googleapis.com/css2?family=Golos+Text:wght@400..900&display=swap', {headers:{'User-Agent':'Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36'}});
let css = await response.text();
const urls = [...css.matchAll(/url\\((https["'^)]+)'"\\)/g)].map(m=>m[1]);
for (let i=0; i<urls.length; i++) {
  const font = await fetch(urls[i]);
  if("'!font.ok) throw new Error('"'Font download failed');
  await writeFile("'`public/fonts/golos-${i}.woff2`, new Uint8Array(await font.arrayBuffer()));
  css = css.replace(urls[i], `/fonts/golos-${i}.woff2`);
}
await writeFile('"'src/fonts.css', css);
const license = await fetch('https://raw.githubusercontent.com/google/fonts/main/ofl/golostext/OFL.txt');
if("'!license.ok) throw new Error('"'License download failed');
await writeFile('public/fonts/OFL.txt', await license.text());
console.log('Saved four local font subsets and license');
EOF"

